import pty, os, subprocess, time, select, pathlib
pathlib.Path("/tmp/fxtest/data.json").write_text('{"a":1,"b":[1,2,3]}')

def run(stdin_mode, stdout_mode, args, cwd="/tmp/fxtest"):
    # stdin_mode: tty, pipe, devnull; stdout_mode tty, pipe
    stdin_slave=None; stdout_slave=None; stdin_master=None; stdout_master=None
    stdin_target=subprocess.PIPE
    stdout_target=subprocess.PIPE
    if stdin_mode=="tty":
        stdin_master, stdin_slave = pty.openpty()
        stdin_target=stdin_slave
    elif stdin_mode=="devnull":
        stdin_target=open("/dev/null","rb")
    if stdout_mode=="tty":
        stdout_master, stdout_slave = pty.openpty()
        stdout_target=stdout_slave
    p = subprocess.Popen(["/workspace/executable"]+args, stdin=stdin_target, stdout=stdout_target, stderr=subprocess.PIPE, cwd=cwd)
    if stdin_slave is not None: os.close(stdin_slave)
    if stdout_slave is not None: os.close(stdout_slave)
    out_tty=b""
    # if stdin pipe, feed
    inp=b'{"a":99}' if stdin_mode=="pipe" else None
    try:
        out_pipe, err = p.communicate(input=inp, timeout=2)
        if stdout_mode=="tty":
            out_pipe=b""
            # read tty
            while True:
                r,_,_=select.select([stdout_master],[],[],0.2)
                if not r: break
                try: d=os.read(stdout_master,65536)
                except: break
                if not d: break
                out_tty+=d
            out=out_tty
        else:
            out=out_pipe
    except subprocess.TimeoutExpired:
        # interactive likely; send q via ??? if stdin tty, write to master; if stdout tty only?
        if stdin_master is not None:
            try: os.write(stdin_master,b"q")
            except: pass
        else:
            p.terminate()
        try:
            out_pipe, err = p.communicate(timeout=2)
            if stdout_mode=="tty":
                out=out_tty  # incomplete
                # try read
                while True:
                    r,_,_=select.select([stdout_master],[],[],0.2)
                    if not r: break
                    try: d=os.read(stdout_master,65536)
                    except: break
                    if not d: break
                    out+=d
            else:
                out=out_pipe
        except Exception as e:
            p.kill(); out=b"<timeout kill>"; err=b""
    finally:
        for m in [stdin_master, stdout_master]:
            if m is not None:
                try: os.close(m)
                except: pass
    return out, err, p.returncode

for sm in ["tty","pipe","devnull"]:
    for om in ["tty","pipe"]:
        for args in [["data.json"],["data.json",".a"],[".a"],[]]:
            o,e,c=run(sm,om,args)
            print(f"stdin={sm} stdout={om} args={args} rc={c} out={o[:500]!r} err={e[:500]!r}")
    print("===")
