#!/usr/bin/env python3
# fx - Terminal JSON viewer and processor (reimplementation)
import sys, os, re, math, base64, random, time, datetime, unicodedata

VERSION = "39.2.0"

# ---------------------------------------------------------------- errors
class ExitProcess(Exception):
    def __init__(self, code=0):
        self.code = code
class PanicError(Exception):
    def __init__(self, msg, stack=None):
        super().__init__(msg)
        self.msg = msg
        self.stack = stack
class GoExitPanic(Exception):
    # Used to emulate Go runtime panics with exit code 2
    def __init__(self, msg):
        self.msg = msg

def emit_panic(msg):
    # Approximate Go panic output (addresses in original are non-deterministic)
    sys.stderr.write(f"panic: {msg}\n\ngoroutine 1 [running]:\nmain.main()\n\tgithub.com/antonmedv/fx/main.go:220 +0xf8b\n")
    return 2

# ---------------------------------------------------------------- JS value types
class UndefinedType:
    _inst = None
    def __new__(cls):
        if cls._inst is None: cls._inst = super().__new__(cls)
        return cls._inst
    def __repr__(self): return "undefined"
    def __bool__(self): return False
UNDEFINED = UndefinedType()

class NullType:
    _inst = None
    def __new__(cls):
        if cls._inst is None: cls._inst = super().__new__(cls)
        return cls._inst
    def __repr__(self): return "null"
    def __bool__(self): return False
NULL = NullType()

class BigIntVal:
    __slots__=('v',)
    def __init__(self, v): self.v = int(v)
    def __repr__(self): return f"{self.v}n"
    def __eq__(self, o): return isinstance(o, BigIntVal) and self.v==o.v
    def __hash__(self): return hash(('bigint', self.v))

class JSSymbol:
    _counter = 0
    def __init__(self, desc=None, registry_key=None):
        JSSymbol._counter += 1
        self.id = JSSymbol._counter
        self.desc = desc  # None means no description, '' etc
        self.registry_key = registry_key
    def __repr__(self): return f"Symbol({self.desc or ''})"

class JSError(Exception):
    """A JS exception. value is the thrown JS value."""
    def __init__(self, value):
        self.value = value
        super().__init__(str(value))

class JSObject:
    def __init__(self, kind='Object'):
        self.props = {}       # str -> value (insertion order)
        self.symprops = {}    # JSSymbol -> value
        self.kind = kind      # 'Object','Date','RegExp','Error','Map','Set','String','Number','Boolean','ArrayBuffer',...
        # extra state by kind
        self.extra = {}
    def __repr__(self):
        return f"<JSObject {self.kind} {list(self.props.keys())[:5]}>"

class JSArray:
    def __init__(self, items=None):
        self.items = list(items) if items else []  # may contain HOLE
        self.props = {}
        self.symprops = {}
        self.kind = 'Array'
    def __repr__(self): return f"<JSArray len={len(self.items)}>"

class _Hole:
    def __repr__(self): return "<hole>"
HOLE = _Hole()

class JSFunction:
    def __init__(self, name='', native=None, params=None, body=None, env=None, source=None, is_arrow=False, is_class=False, is_async=False, construct_impl=None):
        self.name = name
        self.native = native      # callable(this, args, interp) -> value
        self.params = params or []  # list of param descriptors
        self.body = body          # AST node ('block', ...) or expression AST
        self.body_is_expr = False
        self.env = env
        self.source = source or (f"function {name}() {{ [native code] }}" if native else "")
        self.is_arrow = is_arrow
        self.is_class = is_class
        self.is_async = is_async
        self.construct_impl = construct_impl
        self.props = {}
        self.symprops = {}
        self.kind = 'Function'
        # prototype object for constructors
        if not is_arrow:
            proto = JSObject()
            proto.props['constructor'] = self
            self.props['prototype'] = proto
    @property
    def length(self):
        # number of params before first default/rest
        n = 0
        for p in self.params:
            if isinstance(p, dict) and (p.get('default') is not None or p.get('rest')):
                break
            n += 1
        return n
    def __repr__(self): return f"<JSFunction {self.name}>"

class JSRegExpVal:
    def __init__(self, pattern, flags=''):
        self.pattern = pattern
        self.flags = flags
        self.props = {}
        self.lastIndex = 0
    def __repr__(self): return f"/{self.pattern}/{self.flags}"

class JSDateVal:
    def __init__(self, ms):
        self.ms = ms  # float, nan if invalid
        self.props = {}

# well-known / global symbols
SYM_ITERATOR = JSSymbol('Symbol.iterator'); SYM_ITERATOR.desc='Symbol.iterator'
SYM_TO_PRIMITIVE = JSSymbol('Symbol.toPrimitive'); SYM_TO_PRIMITIVE.desc='Symbol.toPrimitive'
SYM_TO_STRING_TAG = JSSymbol('Symbol.toStringTag'); SYM_TO_STRING_TAG.desc='Symbol.toStringTag'
SYM_HAS_INSTANCE = JSSymbol('Symbol.hasInstance'); SYM_HAS_INSTANCE.desc='Symbol.hasInstance'
SKIP_SYMBOL = JSSymbol('skip')

def is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def js_typeof(v):
    if v is UNDEFINED: return 'undefined'
    if v is NULL: return 'object'
    if isinstance(v, bool): return 'boolean'
    if is_number(v): return 'number'
    if isinstance(v, BigIntVal): return 'bigint'
    if isinstance(v, str): return 'string'
    if isinstance(v, JSSymbol): return 'symbol'
    if isinstance(v, JSFunction): return 'function'
    if isinstance(v, RawNode): return raw_typeof(v)
    return 'object'

# JS Number -> string
def js_num_to_string(x):
    if isinstance(x, BigIntVal): return str(x.v)
    x = float(x)
    if math.isnan(x): return 'NaN'
    if math.isinf(x): return 'Infinity' if x>0 else '-Infinity'
    if x == 0: return '0'
    # Use Python repr for shortest round-trip, then adapt to JS rules
    ax = abs(x)
    # Python repr for floats: e.g. 1e+20, 1.0, 0.0001, 1e-07
    if 1e-6 <= ax < 1e21:
        # decimal notation
        r = repr(x)
        if 'e' in r or 'E' in r:
            # expand to decimal
            r = expand_exp(x)
        if r.endswith('.0'): r = r[:-2]
        return r
    else:
        # exponential: mantissa (no trailing .0), e+XX / e-XX, exponent no leading zeros
        r = repr(x)
        if 'e' in r:
            mant, exp = r.split('e')
            ei = int(exp)
            if mant.endswith('.0'): mant = mant[:-2]
            return f"{mant}e{'+' if ei>=0 else '-'}{abs(ei)}"
        return r

def expand_exp(x):
    # format with full decimal expansion using repr mantissa
    s = f"{x:.15e}"  # fallback, may lose precision; better use decimal
    from decimal import Decimal
    d = Decimal(repr(x))
    return format(d, 'f')

def js_bigint_to_string(b):
    return str(b.v if isinstance(b, BigIntVal) else b)

PYEOF
