# ---------------------------------------------------------------- Raw JSON node
MAX_SAFE = 9007199254740991

class RawNode:
    """Preserved parsed JSON node. kind: object,array,string,number,bool,null,undefined,nan,inf"""
    __slots__=('kind','raw','children','key_children','conv','converted','raw_children')
    def __init__(self, kind, raw='', children=None):
        self.kind = kind
        self.raw = raw
