    if v is UNDEFINED: return 'undefined'
    if v is NULL: return 'null'
    if isinstance(v, bool): return 'true' if v else 'false'
    if is_number(v): return js_num_to_string(v)
    if isinstance(v, BigIntVal): return str(v.v)
    if isinstance(v, str): return v
    if isinstance(v, JSSymbol): raise JSError(make_error('TypeError', 'Cannot convert a Symbol value to a string'))
    if isinstance(v, JSArray):
        parts = []
        for item in v.items:
            if item is HOLE or item is NULL or item is UNDEFINED: parts.append('')
            else: parts.append(js_to_string(item))
        return ','.join(parts)
    if isinstance(v, JSDateVal):
        return date_to_string(v.ms)
    if isinstance(v, JSObject):
        prim = js_to_primitive(v, 'string')
        if prim is not v and not isinstance(prim, (JSObject, JSArray, JSFunction)):
            return js_to_string(prim)
        if v.kind == 'String':
            return v.extra.get('value','')
        if v.kind == 'Number':
            return js_num_to_string(v.extra.get('value',0))
        if v.kind == 'Boolean':
            return 'true' if v.extra.get('value') else 'false'
        return '[object Object]'
    if isinstance(v, JSFunction):
        return v.source if v.source else f"function {v.name}() {{ [native code] }}"
    return str(v)

def js_to_primitive(v, hint='default'):
    if isinstance(v, RawNode): v = convert_raw(v)
    if isinstance(v, JSDateVal):
        # Date prefers string for default, number for number hint? simplified
        if hint == 'number': return v.ms
        return date_to_string(v.ms)
    if isinstance(v, JSObject):
        # toString / valueOf lookup (OrdinaryToPrimitive)
        order = ['toString','valueOf'] if hint in ('string','default') else ['valueOf','toString']
        # For Date default is string
        if v.kind == 'Date':
            order = ['toString','valueOf'] if hint != 'number' else ['valueOf','toString']
        for mname in order:
            m = get_property(v, mname)
            if isinstance(m, JSFunction):
                res = call_function(m, v, [])
                if not isinstance(res, (JSObject, JSArray, JSFunction, JSDateVal)):
                    return res
        return '[object Object]' if hint!='number' else float('nan')
    if isinstance(v, JSArray):
        # Array valueOf returns array, toString joins
        if hint == 'number':
            return js_to_string(v)
        return js_to_string(v)
    if isinstance(v, JSFunction):
        return js_to_string(v)
    return v

def js_add(a, b):
    # check bigint mixing first (after primitive conversion)
    pa = js_to_primitive(a, 'default')
    pb = js_to_primitive(b, 'default')
    if isinstance(pa, BigIntVal) or isinstance(pb, BigIntVal):
        if isinstance(pa, BigIntVal) and isinstance(pb, BigIntVal):
            return BigIntVal(pa.v + pb.v)
        raise JSError(make_error('TypeError', 'Cannot mix BigInt and other types, use explicit conversions'))
    if isinstance(pa, str) or isinstance(pb, str):
        return js_to_string(pa) + js_to_string(pb)
    return js_to_number(pa) + js_to_number(pb)

def js_strict_equal(a, b):
    if isinstance(a, RawNode): a = convert_raw(a)
    if isinstance(b, RawNode): b = convert_raw(b)
    ta, tb = js_typeof(a), js_typeof(b)
    # bigint vs number are different types
    if isinstance(a, BigIntVal) or isinstance(b, BigIntVal):
        return isinstance(a, BigIntVal) and isinstance(b, BigIntVal) and a.v == b.v
    if ta != tb: return False
    if a is UNDEFINED or a is NULL: return True
    if isinstance(a, bool): return a == b
    if is_number(a):
        if math.isnan(float(a)) or math.isnan(float(b)): return False
        return float(a) == float(b)
    if isinstance(a, str): return a == b
    if isinstance(a, JSSymbol): return a is b
    return a is b

def js_loose_equal(a, b):
    if isinstance(a, RawNode): a = convert_raw(a)
    if isinstance(b, RawNode): b = convert_raw(b)
    if isinstance(a, BigIntVal) or isinstance(b, BigIntVal):
        if isinstance(a, BigIntVal) and isinstance(b, BigIntVal): return a.v==b.v
        # bigint vs number/string
        other = b if isinstance(a, BigIntVal) else a
        big = a if isinstance(a, BigIntVal) else b
        if is_number(other): return float(big.v) == float(other) and float(other).is_integer()
        if isinstance(other, str):
            try: return BigIntVal(int(other.strip())) .v == big.v if re.fullmatch(r'[+-]?\d+', other.strip()) else False
            except Exception: return False
        if isinstance(other, bool): return js_loose_equal(float(big.v) if abs(big.v)<2**53 else big, other)
        return False
    # same type
    if js_typeof(a) == js_typeof(b) and not (isinstance(a,(JSObject,JSArray,JSFunction)) and isinstance(b,(JSObject,JSArray,JSFunction))):
        return js_strict_equal(a,b)
    if (a is NULL and b is UNDEFINED) or (a is UNDEFINED and b is NULL): return True
    if a is NULL or a is UNDEFINED or b is NULL or b is UNDEFINED: return False
    if isinstance(a, bool): return js_loose_equal(js_to_number(a), b)
    if isinstance(b, bool): return js_loose_equal(a, js_to_number(b))
    if is_number(a) and isinstance(b, str): return float(a) == js_to_number(b) if not math.isnan(js_to_number(b)) else False
    if isinstance(a, str) and is_number(b): return js_to_number(a) == float(b) if not math.isnan(js_to_number(a)) else False
    if isinstance(a, (JSObject,JSArray,JSFunction,JSDateVal)) and isinstance(b,(str,)) or (isinstance(a,str) and isinstance(b,(JSObject,JSArray,JSFunction,JSDateVal))):
