        if isinstance(a,(JSObject,JSArray,JSFunction,JSDateVal)): return js_loose_equal(js_to_primitive(a,'default'), b)
        return js_loose_equal(a, js_to_primitive(b,'default'))
    if isinstance(a,(JSObject,JSArray,JSFunction,JSDateVal)) and is_number(b): return js_loose_equal(js_to_primitive(a,'default'), b)
    if is_number(a) and isinstance(b,(JSObject,JSArray,JSFunction,JSDateVal)): return js_loose_equal(a, js_to_primitive(b,'default'))
    return a is b

def js_less(a, b, left_first=True):
    pa = js_to_primitive(a, 'number')
    pb = js_to_primitive(b, 'number')
    if isinstance(pa, str) and isinstance(pb, str):
        return js_str_compare(pa, pb) < 0
    if isinstance(pa, BigIntVal) or isinstance(pb, BigIntVal):
        # compare bigint vs number/string
        def to_cmp(v):
            if isinstance(v, BigIntVal): return ('b', v.v)
            if isinstance(v, str):
                s=v.strip()
                if re.fullmatch(r'[+-]?\d+', s): return ('b', int(s))
                return ('n', js_to_number(v))
            return ('n', js_to_number(v))
        ca, cb = to_cmp(pa), to_cmp(pb)
        if ca[0]=='b' and cb[0]=='b': return ca[1] < cb[1]
        # convert bigint to float for comparison (may lose but ok)
        fa = float(ca[1]) if ca[0]=='b' else ca[1]
        fb = float(cb[1]) if cb[0]=='b' else cb[1]
        if math.isnan(fa) or math.isnan(fb): return False
        return fa < fb
    na, nb = js_to_number(pa), js_to_number(pb)
    if math.isnan(na) or math.isnan(nb): return False
    return na < nb

def js_str_compare(a, b):
    # JS compares by UTF-16 code units; approximate by encoding
    ab = a.encode('utf-16-be', 'surrogatepass')
    bb = b.encode('utf-16-be', 'surrogatepass')
    if ab < bb: return -1
    if ab > bb: return 1
    return 0

# ---------------------------------------------------------------- errors helpers
def make_error(name, message):
    obj = JSObject(kind='Error')
    obj.props['name'] = name
    obj.props['message'] = message
    obj.extra['error_name'] = name
    obj.extra['error_message'] = message
    return obj

def js_error_to_string(v):
    """Implement e.toString() for a thrown value as goja would."""
    if isinstance(v, RawNode): v = convert_raw(v)
    if isinstance(v, JSObject) and v.kind == 'Error':
        name = v.extra.get('error_name') or js_to_string(v.props.get('name','Error'))
        msg = v.extra.get('error_message')
        if msg is None: msg = js_to_string(v.props.get('message',''))
        if msg == '': return name
        return f"{name}: {msg}"
    if isinstance(v, JSObject):
        # try toString method
        m = get_property(v, 'toString')
        if isinstance(m, JSFunction):
            res = call_function(m, v, [])
            return js_to_string(res)
        return '[object Object]'
    # for primitives, toString: null/undefined produce TypeError in goja when calling e.toString() in catch?
    if v is NULL or v is UNDEFINED:
        raise JSError(make_error('TypeError', "Cannot read property 'toString' of undefined or null"))
    return js_to_string(v)

