# ---------------------------------------------------------------- Raw JSON node
MAX_SAFE = 9007199254740991

class RawNode:
    """Preserved parsed JSON node. kind: object,array,string,number,bool,null,undefined,nan,inf"""
    __slots__=('kind','raw','children','key_children','conv','converted','raw_children')
    def __init__(self, kind, raw='', children=None):
        self.kind = kind
        self.raw = raw
        # children: for array list[RawNode]; for object list[(key_raw_token, RawNode value)] (key decoded lazily)
        self.children = children or []
        self.conv = None
        self.converted = False
    def __repr__(self):
        return f"<Raw {self.kind} {self.raw[:20]!r}>"

def raw_typeof(node):
    k = node.kind
    if k == 'undefined': return 'undefined'
    if k == 'null': return 'object'
    if k == 'bool': return 'boolean'
    if k == 'string': return 'string'
    if k == 'number' or k in ('nan','inf'):
        v = peek_number_kind(node)
        return v
    return 'object'

def peek_number_kind(node):
    # determine if converted value would be bigint or number without marking
    if node.kind in ('nan','inf'): return 'number'
    raw = node.raw
    if re.fullmatch(r'-?\d+', raw):
        try:
            iv = int(raw)
            if abs(iv) > MAX_SAFE: return 'bigint'
        except Exception: pass
    return 'number'

def decode_json_string_content(content):
    """Decode JSON string content (between quotes) like Go encoding/json. Raises PanicError on invalid."""
    out = []
    i = 0
    n = len(content)
    while i < n:
        c = content[i]
        if c == '\\':
            if i+1 >= n:
                raise PanicError("invalid character '\\' in string escape code")
            e = content[i+1]
            if e == '"': out.append('"'); i+=2
            elif e == '\\': out.append('\\'); i+=2
            elif e == '/': out.append('/'); i+=2
            elif e == 'b': out.append('\b'); i+=2
            elif e == 'f': out.append('\f'); i+=2
            elif e == 'n': out.append('\n'); i+=2
            elif e == 'r': out.append('\r'); i+=2
            elif e == 't': out.append('\t'); i+=2
            elif e == 'u':
                hexs = content[i+2:i+6]
                if len(hexs) < 4 or not all(ch in '0123456789abcdefABCDEF' for ch in hexs):
                    bad = hexs[0] if hexs else ''
                    raise PanicError(f"invalid character '{bad}' in \\u hexadecimal character escape")
                code = int(hexs, 16)
                i += 6
                if 0xD800 <= code <= 0xDBFF:
                    # surrogate pair?
                    if content[i:i+2] == '\\u' and i+6 <= n:
                        hex2 = content[i+2:i+6]
                        if all(ch in '0123456789abcdefABCDEF' for ch in hex2):
                            code2 = int(hex2,16)
                            if 0xDC00 <= code2 <= 0xDFFF:
                                out.append(chr(0x10000 + ((code-0xD800)<<10) + (code2-0xDC00)))
                                i += 6
                                continue
                    out.append(chr(0xFFFD))
                elif 0xDC00 <= code <= 0xDFFF:
                    out.append(chr(0xFFFD))
                else:
                    out.append(chr(code))
            else:
                raise PanicError(f"invalid character '{e}' in string escape code")
        elif ord(c) < 0x20:
            raise PanicError(f"invalid character '{c}' in string literal")
        else:
            out.append(c); i+=1
    return ''.join(out)

def decode_json_string_token(token):
    # token includes quotes
    if len(token) >= 2 and token[0]=='"' and token[-1]=='"':
        return decode_json_string_content(token[1:-1])
    return decode_json_string_content(token)

def go_unquote(token):
    """Emulate Go strconv.Unquote for a double-quoted string token. Raises PanicError('invalid syntax')."""
    def bad(): raise PanicError("invalid syntax")
    if len(token) < 2 or token[0] != '"' or token[-1] != '"' or '\n' in token or '\r' in token:
        bad()
    content = token[1:-1]
    out_bytes = bytearray()
    out_chars = []
    i = 0
    # We build a str; handle escapes like Go
    while i < len(content):
        c = content[i]
        if c == '"':
            bad()
        if c == '\\':
            if i+1 >= len(content): bad()
            e = content[i+1]
            simple = {'a':'\a','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\','"':'"'}
            if e in simple:
                out_chars.append(simple[e]); i+=2; continue
            if e == 'x':
                h = content[i+2:i+4]
                if len(h)!=2 or not all(ch in '0123456789abcdefABCDEF' for ch in h): bad()
                out_chars.append(chr(int(h,16))); i+=4; continue
            if e == 'u':
                h = content[i+2:i+6]
                if len(h)!=4 or not all(ch in '0123456789abcdefABCDEF' for ch in h): bad()
                code = int(h,16)
                if 0xD800 <= code <= 0xDFFF or code > 0x10FFFF: bad()
                out_chars.append(chr(code)); i+=6; continue
            if e == 'U':
                h = content[i+2:i+10]
                if len(h)!=8 or not all(ch in '0123456789abcdefABCDEF' for ch in h): bad()
                code = int(h,16)
                if 0xD800 <= code <= 0xDFFF or code > 0x10FFFF: bad()
                out_chars.append(chr(code)); i+=10; continue
            if e in '01234567':
                h = content[i+1:i+4]
                if len(h)!=3 or not all(ch in '01234567' for ch in h): bad()
                val = int(h,8)
                if val > 255: bad()
                out_chars.append(chr(val)); i+=4; continue
            bad()
        else:
            out_chars.append(c); i+=1
    return ''.join(out_chars)

def convert_number_raw(raw):
    """Convert raw number token to JS number/BigInt. May raise PanicError (float range)."""
    if re.fullmatch(r'-?\d+', raw):
        iv = int(raw)
        if abs(iv) > MAX_SAFE:
            return BigIntVal(iv)
        return float(iv)
    # float syntax
    try:
        v = float(raw)
    except Exception:
        raise PanicError(f"strconv.ParseFloat: parsing \"{raw}\": invalid syntax")
    if math.isinf(v) and not re.search(r'[iI]nf', raw):
        # overflow from finite literal e.g. 1e999
        raise PanicError(f"strconv.ParseFloat: parsing \"{raw}\": value out of range")
    return v

def convert_raw(node):
    """Convert RawNode deeply to JS value, marking node as converted. Returns JS value."""
    if node.converted:
        return node.conv
    k = node.kind
    if k == 'object':
        obj = JSObject()
        for key_token, child in node.children:
            key = decode_json_string_token(key_token)
            val = convert_raw(child) if isinstance(child, RawNode) else child
            obj.props[key] = val
        node.conv = obj
    elif k == 'array':
        arr = JSArray()
        arr.items = [convert_raw(ch) if isinstance(ch, RawNode) else ch for ch in node.children]
        node.conv = arr
    elif k == 'string':
        node.conv = decode_json_string_token(node.raw)
    elif k == 'number':
        node.conv = convert_number_raw(node.raw)
    elif k == 'bool':
        node.conv = (node.raw == 'true')
    elif k == 'null':
        node.conv = NULL
    elif k == 'undefined':
        node.conv = UNDEFINED
    elif k == 'nan':
        node.conv = float('nan')
    elif k == 'inf':
        node.conv = float('-inf') if node.raw.startswith('-') else float('inf')
    else:
        node.conv = UNDEFINED
    node.converted = True
    return node.conv

def unwrap(v):
    """If RawNode, convert (marking) and return JS value. Otherwise return as-is."""
    if isinstance(v, RawNode):
        return convert_raw(v)
    return v

def maybe_raw_kind(v):
    if isinstance(v, RawNode): return v.kind
    return None

# ---------------------------------------------------------------- JS conversions
def js_truthy(v):
    if isinstance(v, RawNode):
        cv = convert_raw(v); return js_truthy(cv)
    if v is UNDEFINED or v is NULL: return False
    if isinstance(v, bool): return v
    if is_number(v): return v != 0 and not (isinstance(v,float) and math.isnan(v))
    if isinstance(v, BigIntVal): return v.v != 0
