def token_display(tok):
    if tok.type=='eof': return '}'
    if tok.type=='ident': return None  # identifier special
    if tok.type=='num' or tok.type=='bigint': return 'number'
    if tok.type=='str' or tok.type=='template': return 'string'
    if tok.type=='illegal': return 'ILLEGAL'
    if tok.type=='private': return 'PRIVATE_IDENTIFIER'
    if tok.type=='regex': return '/'
    return tok.value

def unexpected_error(tok):
    if tok.type=='ident': return JSParseError("Unexpected identifier ")
    disp=token_display(tok)
    if disp=='number': return JSParseError("Unexpected number")
    if disp=='string': return JSParseError("Unexpected string")
    if disp=='ILLEGAL': return JSParseError("Unexpected token ILLEGAL")
    if disp=='PRIVATE_IDENTIFIER': return JSParseError("Unexpected token PRIVATE_IDENTIFIER")
    if tok.type=='keyword': return JSParseError(f"Unexpected token {tok.value} ")
    # punctuation
    if tok.value=='...': return JSParseError("Unexpected token ...")
    return JSParseError(f"Unexpected token {tok.value} ")

