    def parse_shift(self): return self._binary(self.parse_additive, ('<<','>>','>>>'))
    def parse_additive(self): return self._binary(self.parse_multiplicative, ('+','-'))
    def parse_multiplicative(self): return self._binary(self.parse_exponent, ('*','/','%'))
    def parse_exponent(self):
        base=self.parse_unary()
        if self.is_punct('**'):
            self.advance(); exp=self.parse_exponent(); return ('binary','**',base,exp)
        return base
    def parse_unary(self):
        if self.cur.type=='punct' and self.cur.value in ('+','-','~','!'):
            op=self.advance(allow_regex=True).value
            e=self.parse_unary(); return ('unary', op, e)
        if self.cur.type=='punct' and self.cur.value in ('++','--'):
            op=self.advance().value; e=self.parse_unary(); return ('update', op, e, True)
        if self.is_kw('typeof','void','delete'):
            op=self.advance(allow_regex=True).value; e=self.parse_unary(); return ('unary', op, e)
        if self.is_kw('await'):
            self.advance(); e=self.parse_unary(); return ('await', e)
        if self.is_kw('yield'):
            # yield as identifier? In non-generator, following token triggers error later as primary ident handling
            pass
        return self.parse_postfix()
    def parse_postfix(self):
        expr=self.parse_member_call()
        if self.cur.type=='punct' and self.cur.value in ('++','--'):
            if self.lex.after_newline: return expr
            op=self.advance().value; return ('update', op, expr, False)
        return expr
    def parse_member_call(self):
        expr=self.parse_primary()
        while True:
            if self.is_punct('.'):
                self.advance()
                if self.cur.type in ('ident','keyword'):
                    name=self.advance(allow_regex=True).value; expr=('member', expr, name, False, False)
                elif self.cur.type=='private':
                    # syntax error special (class private) will be raised as goja-like
                    raise JSParseError("SyntaxError: SyntaxError: Compiler bug: Unknown expression type: *ast.PrivateIdentifier at 7:14")
                else: self.error()
                continue
            if self.is_punct('?.'):
                self.advance()
                if self.is_punct('('):
                    args=self.parse_args(); expr=('call', expr, args, True); continue
                if self.is_punct('['):
                    self.advance(); idx=self.parse_expression(); self.expect_punct(']'); expr=('member', expr, idx, True, True); continue
                if self.cur.type in ('ident','keyword'):
                    name=self.advance(allow_regex=True).value; expr=('member', expr, name, False, True); continue
                self.error()
            if self.is_punct('['):
                self.advance(); idx=self.parse_expression(); self.expect_punct(']'); expr=('member', expr, idx, True, False); continue
            if self.is_punct('('):
                args=self.parse_args(); expr=('call', expr, args, False); continue
            if self.cur.type=='template':
                tag=expr; parts=self.advance().value
                texpr=self.template_to_ast(parts); expr=('tagged', tag, texpr); continue
            break
        return expr
    def parse_args(self):
        self.expect_punct('(')
        args=[]
        if self.is_punct(')'):
            self.advance(); return args
        while True:
            if self.is_punct('...'):
                self.advance(); args.append(('spread', self.parse_assignment()))
            else:
                args.append(self.parse_assignment())
            if self.is_punct(','):
                self.advance()
                if self.is_punct(')'): break
                continue
            break
        self.expect_punct(')')
        return args
    def template_to_ast(self, parts):
        out=[]
        for kind, val in parts:
            if kind=='str': out.append(('strpart', val))
            else:
                sub=Parser(val); expr=sub.parse_expression(); out.append(('exprpart', expr))
        return ('template', out)
    def parse_primary(self):
        tok=self.cur
        if tok.type=='num':
            self.advance(allow_regex=False); return ('num', tok.value)
        if tok.type=='bigint':
            self.advance(allow_regex=False); return ('bigint', tok.value)
        if tok.type=='str':
            self.advance(allow_regex=False); return ('str', tok.value)
        if tok.type=='regex':
            self.advance(allow_regex=False); return ('regex', tok.value[0], tok.value[1])
        if tok.type=='template':
            self.advance(allow_regex=False); return self.template_to_ast(tok.value)
        if tok.type=='private':
            raise JSParseError("SyntaxError: SyntaxError: Compiler bug: Unknown expression type: *ast.PrivateIdentifier at 7:14")
        if tok.type=='ident':
            name=self.advance(allow_regex=False).value; return ('ident', name)
        if self.is_kw('this'):
            self.advance(allow_regex=False); return ('this',)
        if self.is_kw('true'):
            self.advance(allow_regex=False); return ('bool', True)
        if self.is_kw('false'):
            self.advance(allow_regex=False); return ('bool', False)
        if self.is_kw('null'):
            self.advance(allow_regex=False); return ('null',)
        if self.is_kw('undefined'):
            self.advance(allow_regex=False); return ('ident','undefined')
        if self.is_kw('function'):
            return self.parse_function_expression()
        if self.is_kw('class'):
            return self.parse_class()
        if self.is_kw('async'):
            # async function expression
            state=self._save(); self.advance()
            if self.is_kw('function'):
                fn=self.parse_function_expression(is_async=True); return fn
            self._restore(state)
            # async as identifier (sloppy)
            self.advance(allow_regex=False); return ('ident','async')
        if self.is_kw('new'):
            self.advance()
            if self.is_punct('.'):
                self.advance()
                # new.target
                if self.cur.type=='ident' and self.cur.value=='target': self.advance(); return ('undef',)
                self.error()
            # new expression: callee is member expression without calls, then optional args
            callee=self.parse_member_call_for_new()
            args=[]
            if self.is_punct('('): args=self.parse_args()
            return ('new', callee, args)
        if self.is_punct('('):
            self.advance(); expr=self.parse_expression(); self.expect_punct(')'); return expr
        if self.is_punct('['):
            return self.parse_array_literal()
        if self.is_punct('{'):
            return self.parse_object_literal()
        if self.is_kw('yield'):
            # treat as identifier for error compatibility? Original gives Unexpected number for yield 1: parse yield as identifier then next token num causes syntax error at expression end
            self.advance(allow_regex=False); return ('ident','yield')
        if self.is_kw('let'):
            raise JSParseError("Unexpected identifier")
        if tok.type=='keyword':
            # unexpected keywords like throw/if etc
            self.error(tok)
        self.error(tok)
    def parse_member_call_for_new(self):
        expr=self.parse_primary()
        while True:
            if self.is_punct('.'):
                self.advance()
                if self.cur.type in ('ident','keyword'): name=self.advance().value; expr=('member', expr, name, False, False)
                else: self.error()
                continue
            if self.is_punct('['):
                self.advance(); idx=self.parse_expression(); self.expect_punct(']'); expr=('member', expr, idx, True, False); continue
            break
        return expr
    def parse_function_expression(self, is_async=False):
        # cur is 'function'
        self.advance()
        generator=False
        if self.is_punct('*'): self.advance(); generator=True
        name=''
        if self.cur.type=='ident': name=self.advance().value
        params=self.parse_params()
        body=self.parse_block_statements()
        return ('func', name, params, body, is_async, generator)
    def parse_block_statements(self):
        self.expect_punct('{')
        stmts=[]
        while not self.is_punct('}'):
            if self.cur.type=='eof': self.error()
            stmts.append(self.parse_statement())
        self.expect_punct('}')
        return ('block', stmts)
    def parse_class(self):
        self.advance() # class
        name=''
        if self.cur.type=='ident': name=self.advance().value
        extends=None
        if self.is_kw('extends'): self.advance(); extends=self.parse_assignment()
        self.expect_punct('{')
        methods=[]
        while not self.is_punct('}'):
            if self.cur.type=='eof': self.error()
            if self.is_punct(';'): self.advance(); continue
            is_static=False; kind='method'; is_async=False
            # modifiers
            while True:
                if self.is_kw('static') :
                    # peek next: if it's a name, treat as modifier, if '(' it's a method named static
                    state=self._save(); self.advance()
                    if self.is_punct('('): self._restore(state); break
                    if self.is_punct('{'): 
                        # static block - skip
                        self.parse_block_statements(); is_static='block'; break
                    is_static=True; continue
                if self.is_kw('async'):
                    state=self._save(); self.advance()
                    if self.is_punct('('): self._restore(state); break
                    is_async=True; continue
                if self.is_kw('get','set'):
                    state=self._save(); kw=self.advance().value
                    if self.is_punct('('): self._restore(state); break
                    kind=kw; continue
                if self.is_punct('*'): self.advance(); continue
                break
            if is_static=='block': continue
            # method name
            if self.cur.type in ('ident','keyword'): mname=self.advance().value; keynode=('str',mname)
            elif self.cur.type=='str': keynode=('str', self.advance().value)
            elif self.cur.type=='num': keynode=('str', js_num_to_string(self.advance().value))
            elif self.is_punct('['):
                self.advance(); keynode=self.parse_assignment(); self.expect_punct(']')
            elif self.cur.type=='private': raise JSParseError("SyntaxError: SyntaxError: Compiler bug: Unknown expression type: *ast.PrivateIdentifier at 7:14")
            else: self.error()
            if self.is_punct('('):
                params=self.parse_params(); body=self.parse_block_statements()
                fn=('func', keynode[1] if keynode[0]=='str' else '', params, body, is_async, False)
                methods.append((keynode, kind, fn, is_static))
            elif self.is_punct('=',';') or self.is_punct('}'):
                # class field
                default=None
                if self.is_punct('='):
                    self.advance(); default=self.parse_assignment()
                self.eat_semi()
                methods.append((keynode, 'field', default, is_static))
            else: self.error()
        self.expect_punct('}')
        return ('class', name, extends, methods)
    def parse_array_literal(self):
        self.expect_punct('[')
        elems=[]
        while not self.is_punct(']'):
            if self.is_punct(','):
                elems.append(None); self.advance(); continue
            if self.is_punct('...'):
                self.advance(); elems.append(('spread', self.parse_assignment()))
            else:
                elems.append(self.parse_assignment())
            if self.is_punct(','):
                self.advance(); continue
            break
        self.expect_punct(']')
        return ('array', elems)
    def parse_object_literal(self):
        self.expect_punct('{')
        props=[]
        while not self.is_punct('}'):
            if self.is_punct('...'):
                self.advance(); props.append(('spread', self.parse_assignment()))
            else:
                # method / get / set / async
                kind='init'
                if self.is_kw('get','set'):
                    state=self._save(); kw=self.advance().value
                    if self.is_punct(':') or self.is_punct(',') or self.is_punct('}'): self._restore(state)
                    else: kind=kw
                elif self.is_kw('async'):
                    state=self._save(); self.advance()
                    if self.is_punct(':') or self.is_punct(',') or self.is_punct('}'): self._restore(state)
                    else: kind='async'
                elif self.is_punct('*'):
                    self.advance(); kind='generator'
                # key
                if self.cur.type in ('ident','keyword'):
                    key=self.advance().value; keynode=('str',key)
                elif self.cur.type=='str': keynode=('str', self.advance().value)
                elif self.cur.type=='num': keynode=('str', js_num_to_string(self.advance().value))
                elif self.cur.type=='bigint': keynode=('str', str(self.advance().value))
                elif self.is_punct('['):
                    self.advance(); keynode=('computed', self.parse_assignment()); self.expect_punct(']')
                else: self.error()
                if self.is_punct('('):
                    params=self.parse_params(); body=self.parse_block_statements()
                    fn=('func', keynode[1] if keynode[0]=='str' else '', params, body, kind=='async', kind=='generator')
                    props.append(('method', keynode, fn, kind))
                elif self.is_punct(':'):
                    self.advance(); val=self.parse_assignment(); props.append(('prop', keynode, val))
                elif self.is_punct('='):
                    # shorthand with default (in destructuring assignment contexts) approximate as shorthand
                    self.advance(); default=self.parse_assignment(); props.append(('shortdef', keynode, default))
                else:
                    if keynode[0]!='str': self.error()
                    props.append(('shorthand', keynode))
            if self.is_punct(','):
                self.advance(); continue
            break
        self.expect_punct('}')
        return ('object', props)

    # ---------- statements ----------
    def parse_statement(self):
        if self.is_punct('{'): return self.parse_block_statements()
        if self.is_punct(';'): self.advance(); return ('empty',)
        if self.is_kw('return'):
            self.advance()
            if self.is_punct(';') or self.is_punct('}') or self.cur.type=='eof':
                self.eat_semi(); return ('return', None)
            expr=self.parse_expression(); self.eat_semi(); return ('return', expr)
        if self.is_kw('let','const','var'):
            kind=self.advance().value; decls=self.parse_declarations(); self.eat_semi(); return ('vardecl', kind, decls)
        if self.is_kw('function'): 
            fn=self.parse_function_expression(); return ('funcdecl', fn)
        if self.is_kw('class'):
            cl=self.parse_class(); return ('classdecl', cl)
        if self.is_kw('if'):
            self.advance(); self.expect_punct('('); cond=self.parse_expression(); self.expect_punct(')')
            then=self.parse_statement(); els=None
            if self.is_kw('else'): self.advance(); els=self.parse_statement()
            return ('if', cond, then, els)
        if self.is_kw('while'):
            self.advance(); self.expect_punct('('); cond=self.parse_expression(); self.expect_punct(')')
            body=self.parse_statement(); return ('while', cond, body)
        if self.is_kw('do'):
            self.advance(); body=self.parse_statement(); 
            if not self.is_kw('while'): self.error()
            self.advance(); self.expect_punct('('); cond=self.parse_expression(); self.expect_punct(')'); self.eat_semi(); return ('dowhile', body, cond)
        if self.is_kw('for'): return self.parse_for()
        if self.is_kw('throw'):
            self.advance(); expr=self.parse_expression(); self.eat_semi(); return ('throw', expr)
        if self.is_kw('try'):
            self.advance(); block=self.parse_block_statements(); catch=None; fin=None
            if self.is_kw('catch'):
                self.advance(); param=None
                if self.is_punct('('):
                    self.advance()
                    if self.cur.type=='ident': param=('name', self.advance().value)
                    elif self.is_punct('{','['): param=('pattern', self.parse_binding_pattern())
                    self.expect_punct(')')
                cblock=self.parse_block_statements(); catch=(param, cblock)
            if self.is_kw('finally'): self.advance(); fin=self.parse_block_statements()
            return ('try', block, catch, fin)
        if self.is_kw('break','continue'):
            kw=self.advance().value; label=None
            if self.cur.type=='ident': label=self.advance().value
            self.eat_semi(); return (kw, label)
        if self.is_kw('switch'):
            self.advance(); self.expect_punct('('); disc=self.parse_expression(); self.expect_punct(')'); self.expect_punct('{')
            cases=[]
            while not self.is_punct('}'):
                if self.is_kw('case'): self.advance(); test=self.parse_expression(); self.expect_punct(':')
                elif self.is_kw('default'): self.advance(); test=None; self.expect_punct(':')
                else: self.error()
                stmts=[]
                while not self.is_punct('}') and not self.is_kw('case','default'): stmts.append(self.parse_statement())
                cases.append((test, stmts))
            self.expect_punct('}'); return ('switch', disc, cases)
        if self.is_kw('debugger'): self.advance(); self.eat_semi(); return ('empty',)
        # label?
        if self.cur.type=='ident':
            state=self._save(); name=self.advance().value
            if self.is_punct(':'):
                self.advance(); stmt=self.parse_statement(); return ('label', name, stmt)
            self._restore(state)
        expr=self.parse_expression(); self.eat_semi(); return ('expr', expr)
    def parse_declarations(self):
        decls=[]
        while True:
            if self.cur.type=='ident': target=('name', self.advance().value)
            elif self.is_punct('{','['): target=('pattern', self.parse_binding_pattern())
            else: self.error()
            init=None
            if self.is_punct('='): self.advance(); init=self.parse_assignment()
            decls.append((target, init))
            if self.is_punct(','): self.advance(); continue
            break
        return decls
    def parse_for(self):
        self.advance() # for
        await_flag=False
        if self.is_kw('await'): self.advance()
        self.expect_punct('(')
        # for-in/of detection speculative
        if not self.is_punct(';'):
            state=self._save()
