            # We already parsed init; continue classic from ; 
            init_node=init
        else:
            init_node=None
        self.expect_punct(';')
        cond=None
        if not self.is_punct(';'): cond=self.parse_expression()
        self.expect_punct(';')
        upd=None
        if not self.is_punct(')'): upd=self.parse_expression()
        self.expect_punct(')')
        body=self.parse_statement()
        # normalize init
        if init_node and init_node[0]=='expr': init_node=('exprstmt', init_node[1])
        return ('for', init_node, cond, upd, body)
    def parse_declarations_for(self):
        # like parse_declarations but stops before in/of (assignments parsing with allow_in false handled by caller state)
        decls=[]
        while True:
            if self.cur.type=='ident': target=('name', self.advance().value)
            elif self.is_punct('{','['): target=('pattern', self.parse_binding_pattern())
            else: self.error()
            init=None
            if self.is_punct('='): self.advance(); init=self.parse_assignment()
            decls.append((target, init))
            if self.is_punct(','):
                # in for-in/of only one decl allowed normally; but parse
                self.advance(); continue
            break
        return decls

