def js_is_same_value(a,b):
    if is_number(a) and is_number(b):
        if math.isnan(float(a)) and math.isnan(float(b)): return True
        if float(a)==0 and float(b)==0: return math.copysign(1,float(a))==math.copysign(1,float(b))
    return js_strict_equal(a,b)

