def _date_construct(args):
    if not args: return JSDateVal(time.time()*1000)
    if len(args)==1:
        v=args[0]
        if isinstance(v, JSDateVal): return JSDateVal(v.ms)
        if is_number(v): return JSDateVal(float(v))
        if isinstance(v,str): return JSDateVal(parse_date_string(v))
        prim=js_to_primitive(v,'default')
        if is_number(prim): return JSDateVal(float(prim))
        return JSDateVal(parse_date_string(js_to_string(prim)))
    vals=[js_to_integer_or_infinity(a) for a in args]
    while len(vals)<7: vals.append(0 if len(vals)!=2 else 1)
    # Date(y,m,d,...) note day default 1 when constructing with >1 args? JS: day defaults? Actually args beyond provided are undefined -> 0, but day is... For new Date(1970,0) day=1? Use: if len args==2 day=1
    year=int(vals[0]); month=int(vals[1]); day=int(vals[2]) if len(args)>2 else 1
    if 0<=year<=99: year+=1900
    try:
