    m=re.match(r'([+-]?)(0[xX][0-9a-fA-F]+|[0-9]+)', s)
    if radix==0:
        if not m: return float('nan')
        txt=m.group(2)
        if txt.lower().startswith('0x'): return float(int(txt,16)) * (-1 if m.group(1)=='-' else 1)
        return float(int(txt)) * (-1 if m.group(1)=='-' else 1)
    if radix<2 or radix>36: return float('nan')
    # parse longest valid prefix in radix
    sign=-1 if s.startswith('-') else 1
    body=s[1:] if s and s[0] in '+-' else s
    if radix==16 and body.lower().startswith('0x'): body=body[2:]
    digits='0123456789abcdefghijklmnopqrstuvwxyz'
    out=''
    for ch in body.lower():
        if ch in digits and digits.index(ch)<radix: out+=ch
        else: break
    if not out: return float('nan')
    return float(sign*int(out, radix))
