            tmp=JSObject(); s=v.extra.get('value','')
            for i,ch in enumerate(s): tmp.props[str(i)]=ch
            return render_value(tmp, level, parent_kind)
        if v.kind=='Number': return scalar_token(v.extra.get('value',0))
        if v.kind=='Boolean': return scalar_token(v.extra.get('value',False))
        if v.kind in ('Promise',): raise PanicError('Unsupported value type: ptr')
