            for k,val in v.props.items(): tmp.props[k]=val
            return render_value(tmp, level, parent_kind)
    if isinstance(v, JSRegExpVal): return '{}'
    if not is_container(v):
        return scalar_token(v)
    kind=container_kind(v); children=container_children(v)
    indent_str=CURRENT.get('indent','  ')
    if not children:
        return cz('syntax','[]') if kind=='array' else cz('syntax','{}')
    # expanded
    if kind=='array':
        # group inline decision
        present=children
        containers=[ch for _,ch in present if is_container(ch)]
        group=False
        if containers and len(containers)==len(present):
            kinds=set(container_kind(ch) for _,ch in present)
            if len(kinds)==1 and all(can_inline(ch,'array') for _,ch in present): group=True
        lines=[]
        for _,ch in present:
            inline_allowed=group and can_inline(ch,'array')
            txt=render_value_inline_or_expanded(ch, level+1, 'array', inline_allowed)
            lines.append(indent_str*(level+1)+txt)
        return cz('syntax','[')+'\n'+',\n'.join(lines)+'\n'+indent_str*level+cz('syntax',']')
    else:
        lines=[]
        for key,ch in children:
            inline_allowed=can_inline(ch,'object')
            txt=render_value_inline_or_expanded(ch, level+1, 'object', inline_allowed)
            kt=key_token(key, v)
            lines.append(indent_str*(level+1)+kt+cz('syntax',': ')+txt)
        return cz('syntax','{')+'\n'+',\n'.join(lines)+'\n'+indent_str*level+cz('syntax','}')

def render_value_inline_or_expanded(v, level, parent_kind, inline_allowed):
    if isinstance(v, RawNode) and v.converted: v=v.conv
    if inline_allowed and is_container(v) and container_children(v):
        return inline_text(v)
    if is_container(v):
        return render_value(v, level, parent_kind)
    return scalar_token(v)

