    """fx Stringify: renders value as JSON-ish text without trailing newline."""
    if isinstance(v, RawNode) and not v.converted:
        return render_value(v, 0, 'root')
    if isinstance(v, RawNode): v=v.conv
    if v is UNDEFINED: return 'null'
    if isinstance(v,(JSObject,JSArray)) or is_container(v):
        return render_value(v, 0, 'root')
    if isinstance(v,str):
        # __stringify__ path: quoted
        return fx_escape_string(v)
    return scalar_token(v)

def output_result(v, out_write):
    """Main output for a transformed input value."""
    if isinstance(v, JSSymbol) and v is SKIP_SYMBOL: return
    if isinstance(v, RawNode) and not v.converted:
        if v.kind=='string':
            s=go_unquote(v.raw)
            out_write(s+'\n'); return
        if v.kind=='undefined':
            out_write('undefined\n'); return
        out_write(render_value(v,0,'root')+'\n'); return
    if isinstance(v, RawNode): v=v.conv
    if v is UNDEFINED:
        sys.stderr.write('undefined\n'); return
    if v is SKIP_SYMBOL: return
    if isinstance(v, JSSymbol):
        out_write((v.desc or '')+'\n'); return
    if isinstance(v, str):
        out_write(v+'\n'); return
    if isinstance(v, JSFunction):
        raise PanicError('Unsupported value type: func')
    # scalar / container via stringify but for top-level string handled above
    txt=stringify_fx(v)
    # stringify_fx for strings returns quoted; handled; scalars return token
    out_write(txt+'\n')

