# ---------------------------------------------------------------- JSONX input parser
class JSONInputError(Exception):
    def __init__(self, msg, pos):
        self.msg=msg; self.pos=pos
        super().__init__(msg)
    def format(self, text):
        pos=max(0, min(self.pos, len(text)-1)) if text else 0
        line_no=text.count('\n',0,pos)+1
        line_start=text.rfind('\n',0,pos)+1
        line_end=text.find('\n',pos)
        if line_end==-1: line_end=len(text)
        line=text[line_start:line_end]
        dots='.'*(pos-line_start)
        return f"{self.msg} on line {line_no}.\n\n  {line}\n  {dots}^\n\n"

def go_char_repr(c):
    if c is None or c=='\x00': return '\\x00'
    if c=="'": return "\\'"
    if c=='\\': return '\\\\'
    if c=='\n': return '\\n'
    if c=='\r': return '\\r'
    if c=='\t': return '\\t'
    if ord(c)<0x20 or ord(c)==0x7f: return f'\\x{ord(c):02x}'
    return c

class JSONXParser:
    def __init__(self, text, strict=False):
        self.s=text; self.n=len(text); self.i=0; self.strict=strict
        self.yielded=0
    def cur_char(self):
        return self.s[self.i] if self.i<self.n else None
    def err(self, msg, pos=None, eof_clamp=True):
        p=self.i if pos is None else pos
        raise JSONInputError(msg, p)
    def msg_unexpected(self, c, context=None):
        cc=go_char_repr(c)
        if context: return f"Unexpected character '{cc}' {context}"
        return f"Unexpected character '{cc}'"
    def skip(self):
        while self.i<self.n:
            c=self.s[self.i]
            if c in ' \t\r\n': self.i+=1; continue
            if c=='/' and self.i+1<self.n and self.s[self.i+1] in ('/','*'):
                start=self.i
                if self.strict:
                    raise JSONInputError("Comments are not allowed in strict mode", start)
                if self.s[self.i+1]=='/':
                    while self.i<self.n and self.s[self.i]!='\n': self.i+=1
                    continue
                else:
                    end=self.s.find('*/', self.i+2)
                    if end==-1:
                        self.i=self.n
                        raise JSONInputError("Unexpected end of input in comment", self.n)
                    self.i=end+2; continue
            break
    def values(self):
        # generator
        while True:
            self.skip()
            if self.i>=self.n:
                if self.yielded==0 and self.n>0:
                    # force error
                    self.parse_value()
                return
            v=self.parse_value()
            self.yielded+=1
            yield v
    def parse_value(self):
        self.skip()
        if self.i>=self.n:
            raise JSONInputError("Unexpected character '\\x00'", self.i)
        c=self.s[self.i]
        if c=='{': return self.parse_object()
        if c=='[': return self.parse_array()
        if c=='"':
            tok=self.scan_string(); return RawNode('string', raw=tok)
        if c=='-' :
            # special literals?
            sp=self.try_special(self.i+1)
            if sp is not None:
                kind,length=sp; self.i+=1+length; return RawNode(kind, raw=self.s[self.i-(1+length):self.i] if False else self._last_raw(1+length))
            return self.parse_number()
        if c.isdigit(): return self.parse_number()
        if c in 'tfn u':
            return self.parse_keyword_or_special()
        if c in ('N','I','i','n'):
            return self.parse_keyword_or_special()
        raise JSONInputError(f"Unexpected character '{go_char_repr(c)}'", self.i)
    def _last_raw(self, length):
        return self.s[self.i-length:self.i]
    def try_special(self, pos):
        # at pos, check nan/inf variants; returns (kind,length)
        sub=self.s[pos:pos+8]
        if len(sub)>=8 and (sub[:8]=='Infinity' or sub[:8]=='infinity'): return ('inf',8)
        sub3=self.s[pos:pos+3]
        if len(sub3)==3 and sub3.lower()=='nan': return ('nan',3)
        if len(sub3)==3 and sub3.lower()=='inf': return ('inf',3)
        return None
    def parse_keyword_or_special(self):
        c=self.s[self.i]
        # specials starting with n/N/i/I
        if c in ('N','I','i','n'):
            sp=self.try_special(self.i)
            if sp is not None:
                kind,length=sp; start=self.i; self.i+=length; return RawNode(kind, raw=self.s[start:self.i])
            if c=='N':
                # error at next char
                raise JSONInputError(f"Unexpected character '{go_char_repr(self.s[self.i+1] if self.i+1<self.n else None)}'", self.i+1)
            if c in ('I','i'):
                raise JSONInputError(f"Unexpected character '{go_char_repr(c)}'", self.i)
            # c == 'n' falls through to null parsing
        expected=None
        if c=='t': expected='true'
        elif c=='f': expected='false'
        elif c=='n': expected='null'
        elif c=='u': expected='undefined'
        else:
            raise JSONInputError(f"Unexpected character '{go_char_repr(c)}'", self.i)
        # read letters
        j=self.i
        while j<self.n and self.s[j].isalpha(): j+=1
        token=self.s[self.i:j]
        if token==expected:
            self.i=j
            if expected=='true': return RawNode('bool', raw='true')
            if expected=='false': return RawNode('bool', raw='false')
            if expected=='null': return RawNode('null', raw='null')
            return RawNode('undefined', raw='undefined')
        # error determination
        # find prefix mismatch
        if token.startswith(expected) and len(token)>len(expected):
            pos=self.i+len(expected); ch=token[len(expected)]
            raise JSONInputError(f"Unexpected character '{go_char_repr(ch)}' in keyword", pos)
        # truncated at EOF?
        if j>=self.n and expected.startswith(token):
            raise JSONInputError("Unexpected character '\\x00' in keyword", self.n)
        # mismatch inside
        k=0
        while k<min(len(token),len(expected)) and token[k]==expected[k]: k+=1
        if k < len(token) and k < len(expected):
            raise JSONInputError(f"Unexpected character '{go_char_repr(token[k])}' in keyword", self.i+k)
        # shorter token followed by delimiter
        raise JSONInputError(f"Unexpected character '{go_char_repr(self.s[j] if j<self.n else None)}'", j)
