class TNode:
    def __init__(self, raw, parent=None, key=None, key_token=None, index=None):
        self.raw=raw; self.parent=parent; self.key=key; self.key_token=key_token; self.index=index
        self.children=[]; self.collapsed=False
        self.depth=0 if parent is None else parent.depth+1
