    def is_container(self): return isinstance(self.raw, RawNode) and self.raw.kind in ('object','array')
    @property
    def kind(self): return self.raw.kind if isinstance(self.raw, RawNode) else 'value'
    def path(self):
        if self.parent is None: return ''
