def handle_comp(args, argv0):
    comp_val=''
    i=0
    while i < len(args):
        a=args[i]
        if a=='--': break
        if len(a)>1 and a[0]=='-' and a!='-':
            name=a[2:] if a.startswith('--') else a[1:]
            if '=' in name: key,val=name.split('=',1); has=True
            else: key,val,has=name,'',False
            if key!='comp':
                write_err(f"flag provided but not defined: -{key}\nUsage of {argv0}:\n  -comp string\n    \t\n")
                return 2
            if has: comp_val=val
            else:
                if i+1>=len(args):
                    write_err(f"flag needs an argument: -comp\nUsage of {argv0}:\n  -comp string\n    \t\n")
                    return 2
                comp_val=args[i+1]; i+=1
        else:
            break
        i+=1
    if comp_val=='bash': write_out('complete -o filenames -C fx fx\n')
    elif comp_val=='zsh': write_out(COMP_ZSH_SCRIPT)
    elif comp_val=='fish': write_out("complete --command fx --arguments '(COMP_FISH=(commandline -cp) fx)'\n")
    else: write_out('unknown shell type\n')
