def format_go_open_error(path, e):
    if isinstance(e, IsADirectoryError) or (getattr(e,'errno',None)==21):
        return f"read {path}: is a directory\n"
    errname=e.strerror or str(e)
    # Go strerror lowercases first? strerror is already lower
    return f"open {path}: {errname}\n"

def raw_lines(text):
    if text=='': return []
    parts=re.split(r'\r\n|\r|\n', text)
    if text.endswith(('\n','\r')) and parts and parts[-1]=='': parts.pop()
    return parts

def game_of_life():
    import termios, tty, select
    # try to use tty
    out=sys.stdout
    try:
        cols, rows=os.get_terminal_size()
    except Exception: cols, rows=80,24
    in_fd=0
    old=None
    try: old=termios.tcgetattr(in_fd)
    except Exception: pass
    try:
        if old is not None: tty.setraw(in_fd)
        out.write('\x1b[?1049h\x1b[?25l')
        grid=[[random.random()<0.22 for _ in range(cols)] for _ in range(rows*2)]
        while True:
            # render
            frame=[]
            for y in range(rows):
                chars=[]
                for x in range(cols):
                    top=grid[2*y][x]; bot=grid[2*y+1][x] if 2*y+1<len(grid) else False
                    chars.append('█' if top and bot else ('▀' if top else ('▄' if bot else ' ')))
                frame.append(''.join(chars).rstrip())
            out.write('\x1b[H'+'\r\n'.join(frame))
            out.flush()
            time.sleep(0.12)
            # next generation
            h=len(grid); w=cols
            new=[[False]*w for _ in range(h)]
            for yy in range(h):
                for xx in range(w):
                    cnt=0
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            if dx==0 and dy==0: continue
                            nx,ny=xx+dx, yy+dy
                            if 0<=nx<w and 0<=ny<h and grid[ny][nx]: cnt+=1
                    new[yy][xx]=(cnt==3) or (grid[yy][xx] and cnt==2)
            grid=new
            # keys nonblocking
            r,_,_=select.select([in_fd],[],[],0)
            if r:
                data=os.read(in_fd, 32)
                if b'q' in data or b'\x1b' in data or b'\x03' in data: break
    except KeyboardInterrupt: pass
    finally:
        try: out.write('\x1b[?25h\x1b[?1049l')
        except Exception: pass
        if old is not None:
            try: termios.tcsetattr(in_fd, termios.TCSADRAIN, old)
            except Exception: pass
    return 0

