def jsonx_from_python(v):
    if v is None: return RawNode('null', raw='null')
    if v is True: return RawNode('bool', raw='true')
    if v is False: return RawNode('bool', raw='false')
    if isinstance(v, str): return RawNode('string', raw=fx_escape_string(v))
    if isinstance(v, int): return RawNode('number', raw=str(v))
    if isinstance(v, float):
        if math.isnan(v): return RawNode('nan', raw='NaN')
        if math.isinf(v): return RawNode('inf', raw='Infinity' if v>0 else '-Infinity')
        return RawNode('number', raw=js_num_to_string(v))
    if isinstance(v, list): return RawNode('array', children=[jsonx_from_python(x) for x in v])
    if isinstance(v, dict): return RawNode('object', children=[(fx_escape_string(str(k)), jsonx_from_python(val)) for k,val in v.items()])
    return RawNode('string', raw=fx_escape_string(str(v)))

def interactive_from_text(text, filename, file_path, yaml_flag=False, toml_flag=False, raw_flag=False, strict_flag=False):
    # obtain root raw
    root_raw=None; error_msg=None
    try:
        if raw_flag:
            lines=raw_lines(text)
            root_raw=RawNode('string', raw=fx_escape_string(lines[0])) if lines else RawNode('string', raw='""')
            if len(lines)>1:
                # use array of lines as root? (interactive raw streams: first value behavior approx)
                root_raw=RawNode('array', children=[RawNode('string', raw=fx_escape_string(l)) for l in lines])
        elif yaml_flag:
            vals=parse_yaml_documents(text)
            if vals: root_raw=jsonx_from_python(vals[0])
            else: root_raw=RawNode('null', raw='null')
        elif toml_flag:
            try: root_raw=jsonx_from_python(parse_toml(text))
            except TOMLError: raise PanicError('([]uint8) 0xc000012390')
        else:
            parser=JSONXParser(text, strict_flag)
            vals=parser.values()
            try:
                root_raw=next(vals)
            except StopIteration:
                root_raw=RawNode('null', raw='null')
    except JSONInputError as e:
        write_out(e.format(text))
        root_raw=RawNode('object', children=[])
    except YAMLError as e:
        write_out(e.format(text)); root_raw=RawNode('object', children=[])
    return run_interactive(root_raw, text, filename, file_path=file_path)

if __name__=='__main__':
    sys.setrecursionlimit(100000)
    try:
        rc=main()
    except PanicError as e:
        rc=emit_panic(e.msg)
    except ExitProcess as e:
        rc=e.code
    except BrokenPipeError:
        rc=0
    sys.exit(rc)
